189	
190	// TestZeroDedupSubnormalConflictsWithZero 确认 5e-324 仍是可区分的非零值：
191	// 已存零（正零或负零）后向同一位置提交它必须冲突，整批拒绝——本批前面的
192	// 合法新增点不提交，冲突信息给出序列、时间戳、判定冲突时的零值（保留已存
193	// 符号）与提交的极小值，原有的零也不能被替换。反向提交（先存 5e-324 再
194	// 提交零）同样冲突。
195	func TestZeroDedupSubnormalConflictsWithZero(t *testing.T) {
196		for _, zero := range []struct {
197			spelling string
198			neg      bool
199		}{{"0", false}, {"-0.0", true}} {
200			store := NewMetricStore()
201			mustOK(t, store, sampleLineZero(1000, zero.spelling))
202	
203			// 第一个点是合法新增（ts=2000），第二个点才是冲突：整批拒绝。
204			lerr := mustFail(t, store, `[
205				{"name":"m","timestamp":2000,"value":1},
206				{"name":"m","timestamp":1000,"value":5e-324}
207			]`)
208			if lerr.Index != 2 || lerr.Conflict == nil {
209				t.Fatalf("stored %s: expected conflict at index 2, got %+v", zero.spelling, lerr)
210			}
211			c := lerr.Conflict
212			if c.Series.Name != "m" || len(c.Series.Labels) != 0 || c.Timestamp != 1000 {
213				t.Fatalf("stored %s: conflict identity = %+v, want m{} ts=1000", zero.spelling, c)
214			}
215			if c.Existing != 0 || math.Signbit(c.Existing) != zero.neg {
216				t.Fatalf("stored %s: existing = %v (neg=%v), want the stored zero with neg=%v",
217					zero.spelling, c.Existing, math.Signbit(c.Existing), zero.neg)
218			}
219			if c.Submitted != 5e-324 {
220				t.Fatalf("stored %s: submitted = %v, want 5e-324", zero.spelling, c.Submitted)
221			}
222			wantZeroText := "0"
223			if zero.neg {
224				wantZeroText = "-0"
225			}
226			if !strings.Contains(lerr.Error, "already has value "+wantZeroText) ||
227				!strings.Contains(lerr.Error, "submitted 5e-324") {
228				t.Fatalf("stored %s: error must name %s and 5e-324, got %q",
229					zero.spelling, wantZeroText, lerr.Error)
230			}
231	
232			// 整批回滚：ts=2000 的新增点不留下，ts=1000 的零点（含符号）不被替换。
233			q := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":3000}`)
234			if len(q.Series) != 1 || q.Series[0].Count != 1 || q.Series[0].Average != 0 {
235				t.Fatalf("stored %s: query after conflict = %+v, want only the original zero point",
236					zero.spelling, q.Series)
237			}
238			res := mustOK(t, store, `[]`)
239			p := res.Series[0].Points[0]
240			if p.Value != 0 || math.Signbit(p.Value) != zero.neg {
241				t.Fatalf("stored %s: original zero sign changed after conflict, got %+v",
242					zero.spelling, p)
243			}
244		}
245	
246		// 反向：先存 5e-324，再提交零也必须冲突，existing 是极小值、submitted 是零。
247		store := NewMetricStore()
248		mustOK(t, store, sampleLineZero(1, "5e-324"))
249		lerr := mustFail(t, store, sampleLineZero(1, "0"))
250		if lerr.Index != 1 || lerr.Conflict == nil {
251			t.Fatalf("reverse direction expected conflict at index 1, got %+v", lerr)
252		}
253		if lerr.Conflict.Existing != 5e-324 || lerr.Conflict.Submitted != 0 ||
254			math.Signbit(lerr.Conflict.Submitted) {
255			t.Fatalf("reverse conflict = %+v, want existing=5e-324 submitted=+0", lerr.Conflict)
256		}
257	}
258	
259	// TestZeroDedupDuplicateDoesNotRewriteConflictExisting 回归保障：同一批内先遇到
260	// 等值重复、随后在同一位置发生冲突时，冲突报告的 existing 与文字原因必须如实
261	// 对应首次接受的已存值，不能被本批被忽略的重复采样改写。
262	//
263	//   - 已存正零时，本批先提交负零（重复、忽略）再提交 5e-324（冲突）：
264	//     existing 是正零，文字原因显示 "already has value 0" 而不是 -0。
265	//   - 已存负零时，本批先提交正零再提交非零值：existing 与文字原因都保留负零符号。
266	//   - 该位置此前未写入时，existing 取本批首次接受的值（含零值符号），
267	//     后续等值重复（无论重复几次、用哪种零写法）都不替换它。
268	//   - 发生冲突后整批（含前面的合法新增点）都不提交，已存原值保持原样。
269	func TestZeroDedupDuplicateDoesNotRewriteConflictExisting(t *testing.T) {
270		// 已存正零：批内先重复 -0 再冲突 5e-324，existing 仍是正零。
271		store := NewMetricStore()
272		mustOK(t, store, `[{"name":"cpu","labels":{"host":"a"},"timestamp":1000,"value":0}]`)
273		lerr := mustFail(t, store, `[
274			{"name":"cpu","labels":{"host":"a"},"timestamp":2000,"value":7},
275			{"name":"cpu","labels":{"host":"a"},"timestamp":1000,"value":-0},
276			{"name":"cpu","labels":{"host":"a"},"timestamp":1000,"value":5e-324}
277		]`)
278		assertConflictDetail(t, lerr, 3,
279			`conflict: series cpu{host=a} at timestamp 1000 already has value 0, submitted 5e-324`,
280			"cpu", map[string]string{"host": "a"}, 1000, 0, 5e-324)
281		if math.Signbit(lerr.Conflict.Existing) {
282			t.Fatalf("existing = %v, want +0 (stored sign), not the ignored duplicate -0",
283				lerr.Conflict.Existing)
284		}
285		// 整批回滚：ts=2000 的新增点不留下，只剩原来的正零点。
286		q := mustQuery(t, store, `{"op":"query","name":"cpu","start":0,"end":3000}`)
287		if len(q.Series) != 1 || q.Series[0].Count != 1 || q.Series[0].Average != 0 {
288			t.Fatalf("query after conflict = %+v, want only the original zero point", q.Series)
289		}
290	
291		// 已存负零：批内先重复 +0 再冲突，existing 与文字原因保留负号。
292		store = NewMetricStore()
293		mustOK(t, store, `[{"name":"cpu","labels":{"host":"a"},"timestamp":1000,"value":-0.0}]`)
294		lerr = mustFail(t, store, `[
295			{"name":"cpu","labels":{"host":"a"},"timestamp":1000,"value":0},
296			{"name":"cpu","labels":{"host":"a"},"timestamp":1000,"value":5e-324}
297		]`)
298		assertConflictDetail(t, lerr, 2,
299			`conflict: series cpu{host=a} at timestamp 1000 already has value -0, submitted 5e-324`,
300			"cpu", map[string]string{"host": "a"}, 1000, 0, 5e-324)
301		if !math.Signbit(lerr.Conflict.Existing) {
302			t.Fatalf("existing = %v, want -0 (stored sign)", lerr.Conflict.Existing)
303		}
304	
305		// 位置此前未写入：本批首次接受 -0，随后各种零写法重复多次，
306		// existing 仍取首次接受的 -0；冲突后该位置（连同整批）不留下任何点。
307		store = NewMetricStore()
308		lerr = mustFail(t, store, `[
309			{"name":"m","timestamp":1000,"value":-0},
310			{"name":"m","timestamp":1000,"value":0},
311			{"name":"m","timestamp":1000,"value":0.0},
312			{"name":"m","timestamp":1000,"value":1e-400},
313			{"name":"m","timestamp":1000,"value":-1e-400},
314			{"name":"m","timestamp":1000,"value":5e-324}
315		]`)
316		assertConflictDetail(t, lerr, 6,
317			`conflict: series m{} at timestamp 1000 already has value -0, submitted 5e-324`,
318			"m", map[string]string{}, 1000, 0, 5e-324)
319		if !math.Signbit(lerr.Conflict.Existing) {
320			t.Fatalf("existing = %v, want -0 (first accepted in batch)", lerr.Conflict.Existing)
321		}
322		q = mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":3000}`)
323		if len(q.Series) != 0 {
324			t.Fatalf("query after conflict = %+v, want no committed points", q.Series)
325		}
326	}
327	
328	// TestZeroDedupDistinctTimestampsAndZeroAverages 覆盖写入后的区间查询：
329	// 同一位置被忽略的重复不增加 count；零值出现在不同时间戳时是不同采样点，
330	// 每个已成功提交的点都参与计数；精确均值为零（含正负零混合、+1/-1 抵消）
331	// 时 average 一律输出正零。
332	func TestZeroDedupDistinctTimestampsAndZeroAverages(t *testing.T) {
333		store := NewMetricStore()
334		// 三个不同时间戳各写一个零（写法、符号各不相同）：都是新增点。
335		res := mustOK(t, store, `[
336			{"name":"m","timestamp":1,"value":0},
337			{"name":"m","timestamp":2,"value":-0.0},
338			{"name":"m","timestamp":3,"value":1e-400}
339		]`)
340		if res.Added != 3 || res.Duplicates != 0 || len(res.Series[0].Points) != 3 {
341			t.Fatalf("zeros at distinct timestamps = %+v, want 3 added points", res)
342		}
343		// 同一位置的重复（含舍入成相反符号零的文本）被忽略，不增加 count。
344		res = mustOK(t, store, `[
345			{"name":"m","timestamp":1,"value":-1e-400},
346			{"name":"m","timestamp":2,"value":0.0}
347		]`)
348		if res.Added != 0 || res.Duplicates != 2 {
349			t.Fatalf("duplicate zeros counts = %d/%d, want 0/2", res.Added, res.Duplicates)
350		}
351	
352		q := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":10}`)
353		if len(q.Series) != 1 || q.Series[0].Count != 3 {
354			t.Fatalf("zero query = %+v, want count=3", q.Series)
355		}
356		if q.Series[0].Average != 0 || math.Signbit(q.Series[0].Average) {
357			t.Fatalf("zero query average = %v, want +0", q.Series[0].Average)
358		}
359	
360		// 非零数据精确抵消成零时，average 同样是正零而不是负零。
361		store2 := NewMetricStore()
362		mustOK(t, store2, `[
363			{"name":"n","timestamp":1,"value":1},
364			{"name":"n","timestamp":2,"value":-1}
365		]`)
366		q2 := mustQuery(t, store2, `{"op":"query","name":"n","start":0,"end":10}`)
367		if len(q2.Series) != 1 || q2.Series[0].Count != 2 ||
368			q2.Series[0].Average != 0 || math.Signbit(q2.Series[0].Average) {
369			t.Fatalf("canceling average = %+v, want count=2 average=+0", q2.Series)
370		}
371	}
